use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [test] fn path_prefix_remapping_expand_to_absolute_and_local () { let mapping = & FilePathMapping :: new (vec ! [(path ("/foo") , path ("FOO")) , (path ("/bar") , path ("BAR"))] , FileNameDisplayPreference :: Remapped , FileNameEmbeddablePreference :: LocalAndRemapped ,) ; let working_directory = path ("/foo") ; let working_directory = RealFileName :: Remapped { local_path : Some (working_directory . clone ()) , virtual_name : mapping . map_prefix (working_directory) . 0 . into_owned () , } ; assert_eq ! (working_directory . remapped_path_if_available () , path ("FOO")) ; assert_eq ! (mapping . to_embeddable_absolute_path (RealFileName :: LocalPath (path ("/foo/src/main.rs")) , & working_directory) , RealFileName :: Remapped { local_path : Some (path ("/foo/src/main.rs")) , virtual_name : path ("FOO/src/main.rs") }) ; assert_eq ! (mapping . to_embeddable_absolute_path (RealFileName :: LocalPath (path ("/bar/src/main.rs")) , & working_directory) , RealFileName :: Remapped { local_path : Some (path ("/bar/src/main.rs")) , virtual_name : path ("BAR/src/main.rs") }) ; assert_eq ! (mapping . to_embeddable_absolute_path (RealFileName :: Remapped { local_path : Some (path ("/bar/src/main.rs")) , virtual_name : path ("BAR/src/main.rs") , } , & working_directory) , RealFileName :: Remapped { local_path : Some (path ("/bar/src/main.rs")) , virtual_name : path ("BAR/src/main.rs") }) ; assert_eq ! (mapping . to_embeddable_absolute_path (RealFileName :: Remapped { local_path : None , virtual_name : path ("XYZ/src/main.rs") } , & working_directory) , RealFileName :: Remapped { local_path : None , virtual_name : path ("XYZ/src/main.rs") }) ; }
}